124		if len(branchPatterns) > 0 && strings.TrimSpace(branchPatterns[0]) != "" {
125			branchPattern = strings.TrimSpace(branchPatterns[0])
126		}
127	
128		if info, ok := classifyByPattern(branch, branchPattern, true); ok {
