139	func classifyByPattern(branch, pattern string, task bool) (BranchInfo, bool) {
140		re, names, ok := branchPatternRegexp(pattern)
141		if !ok {
142			return BranchInfo{}, false
143		}
144		matches := re.FindStringSubmatch(branch)
145		if matches == nil {
146			return BranchInfo{}, false
147		}
148		values := map[string]string{}
149		for i, name := range names {
150			values[name] = matches[i+1]
151		}
152		info := BranchInfo{Branch: branch, FeatureID: values["feature_id"]}
153		if task {
154			info.Kind = BranchTask
155			info.TaskID = values["work_id"]
156			if info.FeatureID == "" || info.TaskID == "" {
157				return BranchInfo{}, false
158			}
159			if !workIDRe.MatchString(info.TaskID) {
160				return BranchInfo{}, false
161			}
162			return info, true
163		}
164		info.Kind = BranchFeature
165		if info.FeatureID == "" {
166			return BranchInfo{}, false
167		}
168		return info, true
169	}
