171	func branchPatternRegexp(pattern string) (*regexp.Regexp, []string, bool) {
172		var b strings.Builder
173		var names []string
174		for i := 0; i < len(pattern); {
175			switch {
176			case strings.HasPrefix(pattern[i:], "{feature_id}"):
177				b.WriteString("(.+)")
178				names = append(names, "feature_id")
179				i += len("{feature_id}")
180			case strings.HasPrefix(pattern[i:], "{work_id}"):
181				b.WriteString("([^/]+)")
182				names = append(names, "work_id")
183				i += len("{work_id}")
184			default:
185				b.WriteString(regexp.QuoteMeta(pattern[i : i+1]))
186				i++
187			}
188		}
189		if len(names) == 0 {
190			return nil, nil, false
191		}
192		return regexp.MustCompile("^" + b.String() + "$"), names, true
193	}
194	
195	func featurePatternFromTaskPattern(pattern string) string {
196		idx := strings.Index(pattern, "{work_id}")
197		if idx < 0 {
198			return ""
199		}
200		prefix := pattern[:idx]
201		prefix = strings.TrimRight(prefix, "/-_.")
202		if slash := strings.LastIndex(prefix, "/"); slash >= 0 {
203			tail := prefix[slash+1:]
204			if !strings.Contains(tail, "{feature_id}") {
205				prefix = prefix[:slash]
206			}
207		}
208		if !strings.Contains(prefix, "{feature_id}") {
209			return ""
210		}
211		return prefix
212	}
