221				for _, p := range paths {
222					m := featurePathRe.FindStringSubmatch(p)
223					if m == nil {
224						continue
225					}
226					fid := m[1]
227					if _, dup := seen[fid]; !dup {
228						seen[fid] = struct{}{}
229						ids = append(ids, fid)
230					}
231				}
232			}
233		}
234		return ids
